// ── Sprite image load tracking ──────────────────────────────────────────────────────────
// In web-hosted builds (itch.io etc.) each character layer is its own network fetch, so on a
// slow connection the pieces of one sprite can decode seconds apart — the character assembles
// on screen bit by bit. This set records which image URLs have finished loading (success OR
// failure — a broken file must never hide the rest of the sprite forever); the stage render
// holds a sprite invisible until EVERY layer in its stack is here, so it always appears whole.
const vnLoadedImages = new Set<string>();
const vnWarmImage = (url: string): Promise<void> =>
    new Promise(resolve => {
        if (!url || vnLoadedImages.has(url) || url.startsWith('data:')) {
            if (url) vnLoadedImages.add(url);
            resolve();
            return;
        }
        const img = new Image();
        img.onload = img.onerror = () => { vnLoadedImages.add(url); resolve(); };
        img.src = url;
    });

function isRuntimeDebugEnabled(): boolean {
    try {
        return window.localStorage.getItem('flourish:runtimeDebug') === '1';
    } catch {
        return false;
    }
}

function runtimeDebugLog(...args: unknown[]): void {
    if (!isRuntimeDebugEnabled()) return;
    // eslint-disable-next-line no-console
    console.log(...args);
}

function runtimeDebugWarn(...args: unknown[]): void {
    if (!isRuntimeDebugEnabled()) return;
    // eslint-disable-next-line no-console
    console.warn(...args);
}

// --- Persistent Variable Helpers ---
/** localStorage key for cross-session persistent variables */
/** Find a Label command by name, looking in the preferred scene first and then EVERY other
 *  scene — a hotspot/choice "Jump to label" must work across scenes, not just within the
 *  current one. Returns the owning scene so the caller can switch scenes when needed. */
function findLabelAcrossScenes(
    project: VNProject,
    targetLabel: string,
    preferredSceneId: VNID | null,
): { sceneId: VNID; scene: VNScene; index: number } | null {
    const isLabel = (cmd: VNCommand) =>
        cmd.type === CommandType.Label && (cmd as LabelCommand).labelId === targetLabel;
    if (preferredSceneId) {
        const scene = project.scenes[preferredSceneId];
        const index = scene ? scene.commands.findIndex(isLabel) : -1;
        if (scene && index !== -1) return { sceneId: preferredSceneId, scene, index };
    }
    for (const [sceneId, scene] of Object.entries(project.scenes)) {
        if (sceneId === preferredSceneId || !scene) continue;
        const index = scene.commands.findIndex(isLabel);
        if (index !== -1) return { sceneId: sceneId as VNID, scene, index };
    }
    return null;
}

function getPersistentVarsKey(projectId: string): string {
    return `vn-persistent-vars-${projectId}`;
}

/** Load persistent variables from storage (localStorage or Electron) */
function loadPersistentVariables(projectId: string): Record<string, string | number | boolean> {
    try {
        if (typeof window !== 'undefined' && (window as any).electronAPI?.storage) {
            // Electron storage is async — for initial sync load, fall back to localStorage
        }
        const raw = localStorage.getItem(getPersistentVarsKey(projectId));
        return raw ? JSON.parse(raw) : {};
    } catch {
        return {};
    }
}

/** Save a single persistent variable to storage */
function savePersistentVariables(projectId: string, vars: Record<string, string | number | boolean>): void {
    try {
        if (typeof window !== 'undefined' && (window as any).electronAPI?.storage) {
            (window as any).electronAPI.storage.setItem(getPersistentVarsKey(projectId), vars);
        }
        localStorage.setItem(getPersistentVarsKey(projectId), JSON.stringify(vars));
    } catch (e) {
        console.error('Failed to save persistent variables:', e);
    }
}

// ── Remembered timers ("Remember between play sessions") ───────────────────────────────
// A remembered timer's PROGRESS is stored here so it picks up where it was on the next
// boot. NOT wall-clock: it only advances while the game is open. Same storage pair as
// persistent variables (sync localStorage read; dual write). accMs is deliberately not
// stored — sub-tick precision across sessions isn't worth the churn.
type RememberedTimer = {
    value: number; mode: 'countdown' | 'stopwatch'; intervalSec: number; target: number;
    resetTo: number; loop: boolean; variableId?: VNID; onComplete?: VNUIAction[];
    keepAcrossGames?: boolean; savedAt: number;
};
function getRememberedTimersKey(projectId: string): string {
    return `vn-timers-${projectId}`;
}
function loadRememberedTimers(projectId: string): Record<string, RememberedTimer> {
    try {
        const raw = localStorage.getItem(getRememberedTimersKey(projectId));
        return raw ? JSON.parse(raw) : {};
    } catch { return {}; }
}
function saveRememberedTimers(projectId: string, timers: Record<string, RememberedTimer>): void {
    try {
        if (typeof window !== 'undefined' && (window as any).electronAPI?.storage) {
            (window as any).electronAPI.storage.setItem(getRememberedTimersKey(projectId), timers);
        }
        localStorage.setItem(getRememberedTimersKey(projectId), JSON.stringify(timers));
    } catch (e) {
        console.error('Failed to save timers:', e);
    }
}

/** Build initial variable state: defaults + persistent overrides from storage */
function getInitialVariablesWithPersistent(
    projectVariables: Record<string, any>,
    projectId: string
): Record<string, string | number | boolean> {
    const vars: Record<string, string | number | boolean> = {};
    Object.values(projectVariables).forEach((v: any) => {
        vars[v.id] = v.defaultValue;
    });
    // Layer in any persistent-scope values saved from previous sessions
    const persistentVars = loadPersistentVariables(projectId);
    Object.values(projectVariables).forEach((v: any) => {
        if ((v.scope || 'global') === 'persistent' && persistentVars[v.id] !== undefined) {
            vars[v.id] = persistentVars[v.id];
        }
    });
    return vars;
}

/** Get default values for all local-scope variables in a project */
function getLocalVariableDefaults(projectVariables: Record<string, any>): Record<string, string | number | boolean> {
    const defaults: Record<string, string | number | boolean> = {};
    Object.values(projectVariables).forEach((v: any) => {
        if ((v.scope || 'global') === 'local') {
            defaults[v.id] = v.defaultValue;
        }
    });
    return defaults;
}

